const LEVELS = { debug: 10, info: 20, warn: 30, error: 40 };
function createLogger(min) {
  const out = [];
  const log = (lvl, msg) => { if (LEVELS[lvl] >= LEVELS[min]) out.push(lvl + ':' + msg); };
  return { log, out };
}
const l = createLogger('warn');
l.log('info', 'a'); l.log('error', 'b'); l.log('warn', 'c'); l.log('debug', 'd');
console.log(l.out.join(' '));

