class Bus {
  constructor() { this.topics = new Map(); }
  subscribe(t, fn) {
    if (!this.topics.has(t)) this.topics.set(t, new Set());
    this.topics.get(t).add(fn);
    return () => this.topics.get(t).delete(fn);
  }
  publish(t, msg) { for (const fn of this.topics.get(t) ?? []) fn(msg); }
}
const bus = new Bus();
const out = [];
const off = bus.subscribe('x', (m) => { out.push('A' + m); off(); });
bus.subscribe('x', (m) => out.push('B' + m));
bus.publish('x', 1);
bus.publish('x', 2);
bus.publish('y', 3);
console.log(out.join(' '));

