const tasks = [];
const schedule = (name, at) => {
  tasks.push({ name, at });
  tasks.sort((a, b) => a.at - b.at);
};
schedule('email', 300); schedule('report', 100); schedule('cleanup', 300); schedule('ping', 200);
const now = 300;
const due = [];
while (tasks.length && tasks[0].at <= now) due.push(tasks.shift().name);
console.log(due.join(','), tasks.length);

